-- Node: alt-meds (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Altitude Medications — Dosing","body":"**Acetazolamide (Diamox):**\n• MOA: Carbonic anhydrase inhibitor, induces metabolic acidosis → hyperventilation\n• Prevention: 125 mg PO BID, start 1 day before ascent (RADICAL trial: 125mg superior to 62.5mg)\n• Treatment: 250mg PO BID\n• Pediatric: prevention 1.25 mg/kg q12h (max 125mg); treatment 2.5 mg/kg q12h (max 250mg)\n• Side effects: Paresthesias, dysgeusia, polyuria\n• CI: **Absolute** only with prior anaphylaxis or SJS to a sulfonamide; non-anaphylactic sulfa allergy is a relative CI (supervised pre-trip trial acceptable per WMS 2024). Severe renal/hepatic disease.\n\n**Dexamethasone:**\n• MOA: Reduces vasogenic edema, stabilizes BBB\n• Prevention: 2mg q6h or 4mg q12h\n• AMS treatment: 4mg q6h\n• HACE treatment: 8mg x1, then 4mg q6h\n• Caution: Does not aid acclimatization\n\n**Nifedipine (for HAPE):**\n• MOA: Reduces pulmonary artery pressure\n• Dose: 30mg SR q12h or 20mg SR q8h\n• Use extended-release only\n\n**Sildenafil/Tadalafil (for HAPE):**\n• Alternative to nifedipine; tadalafil 10mg q12h elevated to alternative for prevention (WMS 2024 strong rec). Treatment use is weak rec — only if descent / O2 / hyperbaric / nifedipine unavailable.\n• Sildenafil 50mg q8h, Tadalafil 10mg q12h\n• **Do NOT combine nifedipine with a PDE5 inhibitor** — additive hypotension. Pick one. [1][4]","citation":[1,4],"next":"alt-disposition"}'::jsonb
WHERE id = 'alt-meds' AND tree_id = 'altitude-sickness';

