-- Node: hypo-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Accidental Hypothermia","body":"**Definition:** Core temperature <35°C (95°F) due to environmental exposure.\n\n**\"No one is dead until they are WARM and dead.\"**\n\nRemarkable survivals documented:\n- Lowest survivor (accidental hypothermia): **11.8°C** (53.2°F) — per ERC 2025\n- Lowest survivor (induced hypothermia): **4.0°C**\n- Longest CPR with intact neuro survival: **6 hours 52 minutes**\n\n**Key principle:** Hypothermia is PROTECTIVE if it occurs BEFORE cardiac arrest. Cold brain = reduced metabolic demand = prolonged tolerance to ischemia. [1][2][3]","citation":[1,2,3],"next":"hypo-temp-measurement","calculatorLinks":[{"id":"hypo-temp-convert","label":"Temp Converter"},{"id":"hypo-key-temps","label":"Key Temperatures"},{"id":"hypo-swiss-stage","label":"Swiss Staging"},{"id":"hypo-hope-score","label":"HOPE Score"},{"id":"hypo-resus-criteria","label":"Resus Criteria"},{"id":"hypo-rewarming","label":"Rewarming Guide"},{"id":"hypo-ecmo-transport","label":"ECMO Transport"}],"summary":"Core temp measurement is essential — peripheral thermometers are unreliable in hypothermia","safetyLevel":"warning"}'::jsonb
WHERE id = 'hypo-start' AND tree_id = 'hypothermia';

-- Node: nstemi-dapt-duration (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"DAPT Duration & Special Populations","body":"Standard DAPT: 12 months post-PCI (Class 1, 2025 ACC/AHA ACS)\n• Aspirin 81 mg + P2Y12 inhibitor daily\n\n**High bleeding risk — NEW Class 1 (2025 ACC/AHA):**\n• DAPT × 1 month, then **ticagrelor monotherapy** (ULTIMATE-DAPT, T-PASS)\n• BARC 2–5 bleeding halved without increase in MACCE\n\n**Other de-escalation options after 1–3 months if high bleeding risk:**\n• Switch from ticagrelor/prasugrel to clopidogrel (HOST-REDUCE)\n• Aspirin monotherapy after 1–3 months of DAPT (TWILIGHT — weaker than ticagrelor monotherapy)\n\n**Extended DAPT beyond 12 months:**\n• Consider if high ischemic risk (prior MI, diabetes, multivessel disease)\n• Ticagrelor 60 mg BID (PEGASUS-TIMI 54)\n\nIs this a MINOCA presentation?","citation":[1,9,10],"options":[{"label":"Standard ACS (obstructive CAD)","next":"nstemi-discharge"},{"label":"MINOCA suspected (no obstructive CAD)","description":"Non-obstructive coronaries on angiography","next":"nstemi-minoca"}],"treatment":{"firstLine":{"drug":"Aspirin + P2Y12 inhibitor (DAPT)","dose":"Aspirin 81 mg + Ticagrelor 90 mg BID (or Clopidogrel 75 mg daily)","route":"PO","frequency":"Daily","duration":"12 months standard; may extend to 36 months if high ischemic/low bleeding risk","notes":"Extended DAPT (ticagrelor 60 mg BID) per PEGASUS-TIMI 54 if prior MI, diabetes, or multivessel disease."},"alternative":{"drug":"Ticagrelor monotherapy (high bleeding risk)","dose":"90 mg BID (then 60 mg BID after 12 months if extended)","route":"PO","frequency":"Twice daily","duration":"Continue after 1 month of DAPT in high-bleed-risk ACS (2025 ACC/AHA Class 1)","notes":"NEW 2025 Class 1: 1 month DAPT → ticagrelor monotherapy halves BARC 2-5 bleeding without increase in MACCE (ULTIMATE-DAPT, T-PASS). Preferred over aspirin monotherapy in this scenario."},"monitoring":"Bleeding assessment at each visit. Medication adherence counseling. Do NOT stop P2Y12 without cardiology consultation."},"summary":"Standard 12mo DAPT; NEW 2025 Class 1: 1mo DAPT → ticagrelor monotherapy if high bleed risk (ULTIMATE-DAPT/T-PASS); extend beyond 12mo if high ischemic risk (PEGASUS)"}'::jsonb
WHERE id = 'nstemi-dapt-duration' AND tree_id = 'nstemi';

