-- Node: stroke-ivt-treat (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Administer Thrombolysis","body":"**Preferred:** [Tenecteplase](#/drug/tenecteplase/stroke) 0.25 mg/kg IV bolus (max 25 mg) — single dose over 5 seconds.\n\n**Alternative:** [Alteplase](#/drug/alteplase/stroke) 0.9 mg/kg IV (max 90 mg) — 10% bolus over 1 min, remainder over 60 min.\n\nTenecteplase is preferred per current guidelines due to equivalent efficacy, single bolus administration, and simpler dosing.\n\n[Patient Consent Info](#/info/stroke-consent)\n\n**Post-thrombolysis orders:**\n• BP <180/105 × 24h ([Labetalol](#/drug/labetalol/stroke) or [Nicardipine](#/drug/nicardipine/stroke))\n• Neuro checks q15min × 2h, then q30min × 6h, then q1h × 16h\n• No antithrombotics × 24h\n• No arterial/central lines, NG tube, or Foley × 24h if possible\n• Any neuro decline → emergent NCCT","citation":[1,4,5],"next":"stroke-lvo-check","treatment":{"firstLine":{"drug":"Tenecteplase","dose":"0.25 mg/kg","route":"IV bolus","frequency":"Once","duration":"Single dose over 5 seconds","notes":"Max 25 mg"},"alternative":{"drug":"Alteplase","dose":"0.9 mg/kg","route":"IV","frequency":"Once","duration":"10% bolus over 1 min, remainder over 60 min","notes":"Max 90 mg"},"monitoring":"BP <180/105 x 24h. Neuro checks q15min x 2h, then q30min x 6h, then q1h x 16h. Any decline = emergent NCCT."},"summary":"Tenecteplase 0.25 mg/kg preferred single bolus — BP <180/105 x24h, no antithrombotics x24h, neuro checks q15min","safetyLevel":"critical"}'::jsonb
WHERE id = 'stroke-ivt-treat' AND tree_id = 'stroke';

-- Node: stroke-extended-ivt (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Extended IVT Window (4.5–9h)","body":"Perfusion imaging is required to determine eligibility.\n\nSee [Stroke Imaging Guide](#/info/stroke-imaging) for details on CT perfusion and MRI protocols.\n\n**EXTEND trial criteria (alteplase 4.5–9h):**\n• DWI-FLAIR (diffusion-weighted imaging / fluid-attenuated inversion recovery) mismatch on MRI (DWI+, FLAIR− suggests <4.5h)\n• OR CT perfusion showing salvageable tissue\n• Ischemic core <70 mL\n• Penumbra/core mismatch ratio >1.2\n\n**TRACE-III (2024) / TIMELESS:** Tenecteplase 0.25 mg/kg also supported in extended window 4.5–24h with perfusion mismatch when EVT not available — 2026 AHA/ASA Class IIb.","citation":[5,8,14],"options":[{"label":"Salvageable tissue present","description":"Favorable mismatch on perfusion imaging","next":"stroke-ivt-treat","urgency":"critical"},{"label":"Not eligible for IVT","description":"No mismatch or large completed infarct","next":"stroke-evt-window"}],"summary":"Extended 4.5-9h window requires perfusion imaging — DWI-FLAIR mismatch or CT perfusion with salvageable tissue (core <70mL)"}'::jsonb
WHERE id = 'stroke-extended-ivt' AND tree_id = 'stroke';

